<?php
declare(strict_types=1);
require_once __DIR__ . '/accounts_common.php';
$user=qbook_require_user();qbook_require_role($user,['ADMIN']);production_require_method('POST');$input=production_input();
accounts_endpoint(function() use($user,$input): array {$id=(int)($input['expense_id']??0);if($id<=0)accounts_fail('EXPENSE_REQUIRED');$db=production_db();return accounts_transaction($db,function() use($db,$user,$id): array {$s=$db->prepare("SELECT * FROM qbook_general_expenses WHERE id=? FOR UPDATE");$s->execute([$id]);$e=$s->fetch();if(!$e)accounts_fail('EXPENSE_NOT_FOUND',404);if(!in_array($e['status'],['DRAFT','CORRECTION_REQUIRED'],true))accounts_fail('EXPENSE_LOCKED',409);if($e['bank_account_id']===null||$e['expense_date']===null||$e['amount']===null||trim((string)$e['supplier_name_snapshot'])===''||trim((string)$e['description'])==='')accounts_fail('EXPENSE_SUBMISSION_INCOMPLETE');if($e['supplier_id']!==null)accounts_supplier($db,$e['supplier_id']);$b=$db->prepare("SELECT id FROM qbook_bank_accounts WHERE id=? AND is_active=1");$b->execute([$e['bank_account_id']]);if(!$b->fetch())accounts_fail('ACTIVE_BANK_ACCOUNT_REQUIRED');$lines=accounts_load_expense_lines($db,'qbook_general_expense_lines',$id,true);$total=0;foreach($lines as $line){$total+=accounts_money_minor($line['amount'],false);accounts_expense_lines($db,[['amount'=>$line['amount'],'expense_account_id'=>$line['expense_account_id'],'description'=>$line['item_description'],'quantity'=>$line['quantity'],'unit_price'=>$line['unit_price'],'client_id'=>$line['client_id'],'project_id'=>$line['project_id'],'mixer_id'=>$line['mixer_id']]]);}if($lines===[]||$total!==accounts_money_minor($e['amount'],false))accounts_fail('EXPENSE_LINE_TOTAL_MISMATCH');$receipt=$db->prepare("SELECT id FROM qbook_financial_evidence WHERE source_type='GENERAL_EXPENSE' AND source_record_id=? LIMIT 1");$receipt->execute([$id]);if(!$receipt->fetch()&&trim((string)$e['no_receipt_reason'])==='')accounts_fail('RECEIPT_OR_REASON_REQUIRED');$db->prepare("UPDATE qbook_general_expenses SET status='SUBMITTED',submitted_at=UTC_TIMESTAMP(),reviewed_by=NULL,reviewed_at=NULL,review_reason=NULL WHERE id=?")->execute([$id]);accounts_audit($db,$user